SELECT

FROM content_report
WHERE deleted = 1

    AND handle_status = #{query.handleStatus,jdbcType=INTEGER}


    AND report_type = #{query.reportType,jdbcType=INTEGER}


    AND report_reason = #{query.reportReason,jdbcType=INTEGER}


    AND priority = #{query.priority,jdbcType=INTEGER}


    AND content_id = #{query.contentId,jdbcType=BIGINT}


    AND reporter_user_id = #{query.reporterId,jdbcType=BIGINT}


    AND report_time >= #{query.startTime,jdbcType=TIMESTAMP}


    AND report_time <= #{query.endTime,jdbcType=TIMESTAMP}

ORDER BY priority DESC, report_time ASC

